use std :: fmt :: Show ; trait Something { fn yay < T : Show > (_ : Option < Self > , thing : & [T]) -> String { format ! ("{}" , thing) } } struct X { data : u32 } impl Something for X { fn yay < T : Str > (_ : Option < X > , thing : & [T]) -> String { format ! ("{:s}" , thing [0]) } } fn main () { let arr = & ["one" , "two" , "three"] ; println ! ("{}" , Something :: yay (None ::< X >, arr)) }